function pager(total,page,size,onPage,kind='条',onSize=null,sizeOptions=[10,20,50]){if(!total)return '';const pages=Math.max(1,Math.ceil(total/size));let nums=Array.from({length:pages},(_,i)=>i+1).filter(n=>pages<=7||n===1||n===pages||Math.abs(n-page)<=2),last=0;return `<nav class="pagination" aria-label="分页"><span class="total">共 ${total} ${kind}</span><button aria-label="上一页" onclick="${onPage}(${page-1})" ${page===1?'disabled':''}><img style="transform:rotate(180deg)" src="assets/pagination-chevron-right.svg" alt=""></button>${nums.map(n=>{const gap=last&&n-last>1?'<span>…</span>':'';last=n;return gap+`<button aria-label="第 ${n} 页" ${n===page?'aria-current="page"':''} onclick="${onPage}(${n})">${n}</button>`}).join('')}<button aria-label="下一页" onclick="${onPage}(${page+1})" ${page===pages?'disabled':''}><img src="assets/pagination-chevron-right.svg" alt=""></button>${onSize?select('每页数量',size,sizeOptions.map(n=>({value:n,label:n+(kind==='张'?' 张/页':' 条/页')})),v=>{window[onSize](+v)}):''}${pages>5?`<span style="margin-left:12px">跳至</span><input class="input jump" type="number" aria-label="跳转页码" min="1" max="${pages}" onkeydown="if(event.key==='Enter')${onPage}(Math.min(${pages},Math.max(1,+this.value||1)))"><span>页</span>`:''}</nav>`}
