function reviewModal(){openModal({title:'页面与状态导览',body:`<p class="secondary">示例数据仅在本次预览会话中保存，刷新后恢复初始状态。</p><div class="review-list">${L('卡类列表','closeModal(true);go(\'list\',true)')}<br>${L('卡类详情','closeModal(true);openDetail(cards[0].id)')}<br>${L('新建卡类','closeModal(true);readOnly=false;startEdit(false)')}<br>${L('修改卡类','closeModal(true);readOnly=false;current=cards[0];startEdit(true)')}<br>${L('可使用门店配置','closeModal(true);readOnly=false;current=cards[0];startEdit(true);openStoreConfig()')}<br>${L('批量添加 · 检查示例','showImportExample()')}<br>${L('卡面管理','closeModal(true);go(\'library\',true)')}</div><p class="help">可通过搜索不存在的名称查看空态，通过切换角色查看只读状态。</p>`,cancel:'关闭'})}
