document.addEventListener('click',e=>{if(!e.target.closest('.select'))closeSelects();if(!e.target.closest('.column-settings'))closeColumnSettings()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#column-settings-panel')&&!$('#column-settings-panel').hidden){e.preventDefault();closeColumnSettings(true)}});
document.addEventListener('keydown',e=>{const open=$('.select.open');if(open){if(e.key==='Escape'||e.key==='Tab'){closeSelects();if(e.key==='Escape')e.preventDefault();return}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const opts=[...open.querySelectorAll('[role=option]')].filter(x=>!x.hidden);let n=opts.indexOf(document.activeElement);n=(n+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts[n]?.focus();return}}if(modalState){if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const elements=[...$('.modal').querySelectorAll('button,input,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&x.offsetParent!==null),first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});
