function removeUploadImage(){uploadImage='';modalDirty=true;document.getElementById('art-image-preview').innerHTML=B('选择文件',"document.getElementById('art-file').click()");document.getElementById('art-file').value=''}

function productUpload(){return `<div class="product-upload">${draft.image?`<img src="${draft.image}" alt="商品展示图"><div class="product-overlay"><button aria-label="查看商品展示图" onclick="previewProduct()"><svg viewBox="0 0 24 24"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button><button aria-label="删除商品展示图" onclick="draft.image='';refreshForm()"><svg viewBox="0 0 24 24"><path d="M3 6h18M9 6V3h6v3M6 6v15h12V6"/></svg></button></div>`:`<button class="upload-small" aria-label="上传商品展示图" onclick="document.getElementById('product-file').click()"><span class="plus">+</span></button>`}</div><input hidden type="file" id="product-file" accept="image/png,image/jpeg" onchange="uploadProduct(this.files[0])">`}
function previewProduct(){openModal({title:'商品展示图',body:`<img class="product-preview" src="${draft.image}" alt="商品展示图预览">`,cancel:'关闭'})}

// Option two uses the same form layout for editing and read-only viewing.
function renderDetailV2(){
  const saved={draft,editing,errors};
  try{draft=structuredClone(current);editing=true;errors={};renderEdit()}
  finally{draft=saved.draft;editing=saved.editing;errors=saved.errors}
  const main=$('#main'),form=$('#form-content');
  main.classList.remove('with-footer');
  main.querySelector('.breadcrumb').outerHTML=breadcrumb([['礼品卡卡类管理',"go('list')"],['卡类详情']]);
  main.querySelector('.pagehead').innerHTML=`<h1>卡类详情</h1>${!readOnly?B('修改卡类','startEdit(true)','primary'):''}`;
  main.querySelector('.edit-surface').classList.add('readonly-form');
  form.querySelectorAll('*').forEach(el=>{for(const attribute of [...el.attributes])if(attribute.name.startsWith('on'))el.removeAttribute(attribute.name)});
  form.querySelectorAll('input,textarea').forEach(el=>{
    if(['radio','checkbox','file'].includes(el.type)){el.disabled=true;el.setAttribute('aria-disabled','true');return}
    el.readOnly=true;el.setAttribute('aria-readonly','true');el.removeAttribute('placeholder');
    if(!el.value&&el.type!=='number')el.value='—';
  });
  form.querySelectorAll('.required').forEach(el=>el.remove());
  const imageControl=form.querySelector('[data-field="image"] .field-control');
  imageControl.querySelector('.product-upload').outerHTML=`<div class="product-upload product-readonly">${current.image?`<img src="${current.image}" alt="商品展示图">`:'<div class="readonly-empty">未设置</div>'}</div>`;
  imageControl.querySelector('input[type="file"]')?.remove();
  form.querySelector('[data-field="stores"] .field-control').innerHTML=`<div class="store-info"><button class="store-count-link" onclick="openStoreView('yes')">可用 <b class="num available-count">${current.storeIds.length}</b> 家<img src="assets/identity/chevron-right.svg" alt="" aria-hidden="true"></button><span aria-hidden="true">·</span><button class="store-count-link" onclick="openStoreView('no')">不可用 <b class="num unavailable-count">${stores.length-current.storeIds.length}</b> 家<img src="assets/identity/chevron-right.svg" alt="" aria-hidden="true"></button>${L('导出门店','exportStores(false)')}</div>`;
  ['saleTags','useTags'].forEach(key=>{form.querySelector(`[data-field="${key}"] .field-control`).innerHTML=current[key].length?`<div class="tags">${current[key].map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:'<div class="readonly-empty">未设置</div>'});
  $('#fixed').innerHTML='';
}
